INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$c15069eb$SATQ$, $SATQ$205f5245-08e7-4611-9731-a5ec8b73a181$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Latin America is known to have dozens, if not hundreds, of popular dance forms. Only five of these dances are included in international ballroom dance <span aria-hidden="true">______</span><span class="sr-only">blank</span> rumba, samba, cha-cha-cha, paso doble, and jive&mdash;the last of which is grouped with the other Latin dances despite not having Latin roots.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2a2fc192-0cb1-4525-9fb7-b86108aa19a5","content":"<p>competitions, however:</p>"},{"id":"ac908104-97ee-45e9-afab-b3131258cb55","content":"<p>competitions, however,</p>"},{"id":"85352ab3-27f4-4d1c-9a34-fde93ba9cb16","content":"<p>competitions, however;</p>"},{"id":"e93456a7-fa64-4a30-ba69-918f452057e0","content":"<p>competitions; however,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["2a2fc192-0cb1-4525-9fb7-b86108aa19a5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the punctuation of supplementary elements within a sentence. This choice correctly uses a comma to separate the supplementary adverb "however" from the preceding main clause ("only...competitions"), and it uses a colon to introduce the list of dances that follows ("rumba&hellip;jive"). Further, placing the colon after "however" rather than before indicates that the information in the preceding main clause (only...competitions) is contrary to what might be assumed from the information in the previous sentence (Latin America has many more dance forms).</p><p>Choice B is incorrect. The comma after "however" can&rsquo;t be used in this way to introduce a series ("rumba...jive"). Choice C is incorrect because it isn&rsquo;t conventional to use a semicolon in this way to introduce a series of items, such as the list of dances. Choice D is incorrect because placing the semicolon after "competitions" illogically indicates that the following list of five Latin American dances ("rumba...jive") is contrary to the information in the previous clause (only five Latin American dances are included in international ballroom dance competitions).</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c15069eb","external_id":"205f5245-08e7-4611-9731-a5ec8b73a181","vaultid":null,"uId":"c27f7f4e-19bd-469e-8625-bf4a3686c95d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Latin America is known to have dozens, if not hundreds, of popular dance forms. Only five of these dances are included in international ballroom dance <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> rumba, samba, cha-cha-cha, paso doble, and jive&mdash;the last of which is grouped with the other Latin dances despite not having Latin roots.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"2a2fc192-0cb1-4525-9fb7-b86108aa19a5","content":"<p>competitions, however:</p>"},{"id":"ac908104-97ee-45e9-afab-b3131258cb55","content":"<p>competitions, however,</p>"},{"id":"85352ab3-27f4-4d1c-9a34-fde93ba9cb16","content":"<p>competitions, however;</p>"},{"id":"e93456a7-fa64-4a30-ba69-918f452057e0","content":"<p>competitions; however,</p>"}],"keys":["2a2fc192-0cb1-4525-9fb7-b86108aa19a5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the punctuation of supplementary elements within a sentence. This choice correctly uses a comma to separate the supplementary adverb \"however\" from the preceding main clause (\"only...competitions\"), and it uses a colon to introduce the list of dances that follows (\"rumba&hellip;jive\"). Further, placing the colon after \"however\" rather than before indicates that the information in the preceding main clause (only...competitions) is contrary to what might be assumed from the information in the previous sentence (Latin America has many more dance forms).</p><p>Choice B is incorrect. The comma after \"however\" can&rsquo;t be used in this way to introduce a series (\"rumba...jive\"). Choice C is incorrect because it isn&rsquo;t conventional to use a semicolon in this way to introduce a series of items, such as the list of dances. Choice D is incorrect because placing the semicolon after \"competitions\" illogically indicates that the following list of five Latin American dances (\"rumba...jive\") is contrary to the information in the previous clause (only five Latin American dances are included in international ballroom dance competitions).</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$c21df211$SATQ$, $SATQ$471d4144-80a4-4d23-a0c0-170823a91b45$SATQ$::uuid, $SATQ$1384e7f2-3d61-425a-ac34-c195f283da5e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1959, the film industry debuted Smell-O-Vision. Theaters were fitted with specialized vents that emitted odors at specific points in a <span aria-hidden="true">______</span><span class="sr-only">blank</span> as the scent of roses when roses appeared in a scene. Smell-O-Vision failed to impress, however, with one reviewer declaring it &ldquo;briefly weird and not very interesting.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"23981881-a5ef-4601-91ef-d1d8d8ce04a1","content":"<p>movie such</p>"},{"id":"70f12f58-e311-45e6-b193-e5027f3a87c2","content":"<p>movie; such</p>"},{"id":"b5894612-6ecb-4d72-a2e7-54be36055ec5","content":"<p>movie. Such</p>"},{"id":"da0794be-2912-4064-a5d0-06d39d862e59","content":"<p>movie, such</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["da0794be-2912-4064-a5d0-06d39d862e59"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The comma appropriately separates the nonessential descriptive aside "such as&hellip;scene" from the independent clause "Theaters were&hellip;movie." Since the descriptive example of roses isn&rsquo;t necessary for the sentence to function, it needs to be set off with punctuation.</p><p>Choice A is incorrect. This choice results in a run-on sentence. Since the example of roses isn&rsquo;t necessary for the sentence to function, the descriptive aside "such as&hellip;scene" needs to be separated from the preceding independent clause with some sort of punctuation. Choice B is incorrect. This choice creates a punctuation error. A semicolon can only be used to separate two independent clauses, but "such&hellip;scene" is not an independent clause and couldn&rsquo;t stand on its own as a sentence. Choice C is incorrect. This choice results in a sentence fragment. The descriptive aside "Such&hellip;scene" is not an independent clause and can&rsquo;t stand on its own as a sentence.</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-E005$SATQ$, $SATQ$$SATQ$, $SATQ$4169cc66-ea45-4782-ab51-edc6e6bbddef$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c21df211","external_id":"471d4144-80a4-4d23-a0c0-170823a91b45","vaultid":"1384e7f2-3d61-425a-ac34-c195f283da5e","uId":"81a1ba67-939b-476e-b176-ffb551f226f7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1959, the film industry debuted Smell-O-Vision. Theaters were fitted with specialized vents that emitted odors at specific points in a <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> as the scent of roses when roses appeared in a scene. Smell-O-Vision failed to impress, however, with one reviewer declaring it &ldquo;briefly weird and not very interesting.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"23981881-a5ef-4601-91ef-d1d8d8ce04a1","content":"<p>movie such</p>"},{"id":"70f12f58-e311-45e6-b193-e5027f3a87c2","content":"<p>movie; such</p>"},{"id":"b5894612-6ecb-4d72-a2e7-54be36055ec5","content":"<p>movie. Such</p>"},{"id":"da0794be-2912-4064-a5d0-06d39d862e59","content":"<p>movie, such</p>"}],"keys":["da0794be-2912-4064-a5d0-06d39d862e59"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The comma appropriately separates the nonessential descriptive aside \"such as&hellip;scene\" from the independent clause \"Theaters were&hellip;movie.\" Since the descriptive example of roses isn&rsquo;t necessary for the sentence to function, it needs to be set off with punctuation.</p><p>Choice A is incorrect. This choice results in a run-on sentence. Since the example of roses isn&rsquo;t necessary for the sentence to function, the descriptive aside \"such as&hellip;scene\" needs to be separated from the preceding independent clause with some sort of punctuation. Choice B is incorrect. This choice creates a punctuation error. A semicolon can only be used to separate two independent clauses, but \"such&hellip;scene\" is not an independent clause and couldn&rsquo;t stand on its own as a sentence. Choice C is incorrect. This choice results in a sentence fragment. The descriptive aside \"Such&hellip;scene\" is not an independent clause and can&rsquo;t stand on its own as a sentence.</p>","parenttemplatename":"OSP-KA-BOU-E005","parenttemplateid":"","templateclusterid":"4169cc66-ea45-4782-ab51-edc6e6bbddef","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$c437dd53$SATQ$, $SATQ$97f2d24c-3152-4904-8542-5d10445ee132$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Wanting to celebrate the 100th anniversary of the Alaska Purchase, <span aria-hidden="true">______</span><span class="sr-only">blank</span> up with a motto that best captured the state&rsquo;s unique character. The commission selected &ldquo;North to the Future,&rdquo; submitted by Juneau journalist Richard Peter, as its winning entry.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5d2592eb-4a2c-4e73-8a11-87d9d8c11e5a","content":"<p>a contest sponsored by the Alaska Centennial Commission would award $300 to an individual who came</p>"},{"id":"674171a0-9f43-4a82-ae4d-94af0416d7ec","content":"<p>an award of $300 would go to an individual in a contest sponsored by the Alaska Centennial Commission for coming</p>"},{"id":"81105d96-1acb-43fd-a84e-36698f1fa65a","content":"<p>$300 would be awarded to an individual by the Alaska Centennial Commission in a contest for coming</p>"},{"id":"1f60d157-c5c3-4170-b241-7a67b597acb8","content":"<p>the Alaska Centennial Commission sponsored a contest that would award $300 to an individual who came</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["1f60d157-c5c3-4170-b241-7a67b597acb8"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase "the Alaska Centennial Commission" the subject of the sentence and places it immediately after the modifying phrase "wanting&hellip;Purchase." In doing so, this choice clearly establishes that the Alaska Centennial Commission&mdash;and not another noun in the sentence&mdash;wanted to celebrate the 100th anniversary of the Alaska Purchase.</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase "a contest" immediately after the modifying phrase illogically suggests that the contest wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase "an award of $300" immediately after the modifying phrase illogically suggests that the award of $300 wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase "$300" immediately after the modifying phrase illogically suggests that the $300 wanted to celebrate the 100th anniversary of the Alaska Purchase.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c437dd53","external_id":"97f2d24c-3152-4904-8542-5d10445ee132","vaultid":null,"uId":"67ecea25-af86-4173-bde9-4d48d642e64d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Wanting to celebrate the 100th anniversary of the Alaska Purchase, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> up with a motto that best captured the state&rsquo;s unique character. The commission selected &ldquo;North to the Future,&rdquo; submitted by Juneau journalist Richard Peter, as its winning entry.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5d2592eb-4a2c-4e73-8a11-87d9d8c11e5a","content":"<p>a contest sponsored by the Alaska Centennial Commission would award $300 to an individual who came</p>"},{"id":"674171a0-9f43-4a82-ae4d-94af0416d7ec","content":"<p>an award of $300 would go to an individual in a contest sponsored by the Alaska Centennial Commission for coming</p>"},{"id":"81105d96-1acb-43fd-a84e-36698f1fa65a","content":"<p>$300 would be awarded to an individual by the Alaska Centennial Commission in a contest for coming</p>"},{"id":"1f60d157-c5c3-4170-b241-7a67b597acb8","content":"<p>the Alaska Centennial Commission sponsored a contest that would award $300 to an individual who came</p>"}],"keys":["1f60d157-c5c3-4170-b241-7a67b597acb8"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase \"the Alaska Centennial Commission\" the subject of the sentence and places it immediately after the modifying phrase \"wanting&hellip;Purchase.\" In doing so, this choice clearly establishes that the Alaska Centennial Commission&mdash;and not another noun in the sentence&mdash;wanted to celebrate the 100th anniversary of the Alaska Purchase.</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase \"a contest\" immediately after the modifying phrase illogically suggests that the contest wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase \"an award of $300\" immediately after the modifying phrase illogically suggests that the award of $300 wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase \"$300\" immediately after the modifying phrase illogically suggests that the $300 wanted to celebrate the 100th anniversary of the Alaska Purchase.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$c468db1c$SATQ$, $SATQ$5321cf85-25cc-4b37-9b52-4aa249dafd17$SATQ$::uuid, $SATQ$2ad56276-4fee-4b4d-81e3-d23039092092$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A group of ecologists led by Axel Mith&ouml;fer at the Max Planck Institute for Chemical Ecology in Germany examined the defensive responses of two varieties of the sweet potato <span aria-hidden="true">______</span><span class="sr-only">blank</span> TN57, which is known for its insect resistance, and TN66, which is much more susceptible to pests.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9e22982b-8564-490a-82cf-f8775684d3fd","content":"<p>plant.&nbsp;</p>"},{"id":"114dcf4f-550f-4554-96f6-32b921f4f5bf","content":"<p>plant;</p>"},{"id":"6ba63a9d-8d24-4b93-aaf6-756e94555ee9","content":"<p>plant&nbsp;</p>"},{"id":"1818c821-5334-4992-8735-b6ce64b7e049","content":"<p>plant:</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["1818c821-5334-4992-8735-b6ce64b7e049"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. In this choice, a colon is correctly used to mark the boundary between the main clause (&ldquo;A group&hellip;plant&rdquo;) and the supplementary element (&ldquo;TN57&hellip;pests&rdquo;) and to introduce the following elaboration on the specific varieties of sweet potato plants that were examined. </p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;TN57.&rdquo;&nbsp;&nbsp;Choice B is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause (&ldquo;A group&hellip;plant&rdquo;) and the supplementary element (&ldquo;TN57&hellip;pests&rdquo;). A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce an element that explains or amplifies the information in the preceding clause. Choice C is incorrect because it fails to mark the boundary between the main clause (&ldquo;A group...plant&rdquo;) and the supplementary element (&ldquo;TN57...pests&rdquo;) with appropriate punctuation. </p>$SATQ$, false, 0, $SATQ$OSP-613-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$e09f4865-5c74-4ead-9c73-90018de683dc$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c468db1c","external_id":"5321cf85-25cc-4b37-9b52-4aa249dafd17","vaultid":"2ad56276-4fee-4b4d-81e3-d23039092092","uId":"dbf4bb60-d0df-45c5-a2ef-fdca9b7db2d2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A group of ecologists led by Axel Mith&ouml;fer at the Max Planck Institute for Chemical Ecology in Germany examined the defensive responses of two varieties of the sweet potato <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> TN57, which is known for its insect resistance, and TN66, which is much more susceptible to pests.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9e22982b-8564-490a-82cf-f8775684d3fd","content":"<p>plant.&nbsp;</p>"},{"id":"114dcf4f-550f-4554-96f6-32b921f4f5bf","content":"<p>plant;</p>"},{"id":"6ba63a9d-8d24-4b93-aaf6-756e94555ee9","content":"<p>plant&nbsp;</p>"},{"id":"1818c821-5334-4992-8735-b6ce64b7e049","content":"<p>plant:</p>"}],"keys":["1818c821-5334-4992-8735-b6ce64b7e049"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. In this choice, a colon is correctly used to mark the boundary between the main clause (&ldquo;A group&hellip;plant&rdquo;) and the supplementary element (&ldquo;TN57&hellip;pests&rdquo;) and to introduce the following elaboration on the specific varieties of sweet potato plants that were examined. </p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;TN57.&rdquo;&nbsp;&nbsp;Choice B is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause (&ldquo;A group&hellip;plant&rdquo;) and the supplementary element (&ldquo;TN57&hellip;pests&rdquo;). A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce an element that explains or amplifies the information in the preceding clause. Choice C is incorrect because it fails to mark the boundary between the main clause (&ldquo;A group...plant&rdquo;) and the supplementary element (&ldquo;TN57...pests&rdquo;) with appropriate punctuation. </p>","parenttemplatename":"OSP-613-SEC","parenttemplateid":"","templateclusterid":"e09f4865-5c74-4ead-9c73-90018de683dc","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$c49e946e$SATQ$, $SATQ$58385fcc-c386-4743-8021-f2d3c14f8b66$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>As the fourteenth US librarian of Congress, Carla Hayden has many responsibilities. These include overseeing the Library of Congress&rsquo;s collections, which boast more than 162 million <span aria-hidden="true">______</span><span class="sr-only">blank</span> the US Copyright Office, which registers copyright claims and advises Congress on copyright law; and appointing the US poet laureate.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"47b2505a-b6e6-4e96-bbfd-6dabc7ebedbe","content":"<p>items managing</p>"},{"id":"1cc664ee-54b3-49dc-9614-6fad90b2321f","content":"<p>items<span data-ssml-say-as=\"characters\">,</span> managing</p>"},{"id":"0acf7547-77a9-4b81-be22-a2d5b40909d4","content":"<p>items<span data-ssml-say-as=\"characters\">;</span> managing</p>"},{"id":"b56c6ffe-7ce4-43f9-af4c-7d32c354126d","content":"<p>items<span data-ssml-say-as=\"characters\">.</span> Managing</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0acf7547-77a9-4b81-be22-a2d5b40909d4"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of elements in a complex series. It&rsquo;s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after "items" is conventionally used to separate the first item ("overseeing&hellip;items") and the second item ("managing&hellip;law") in a list of Hayden&rsquo;s responsibilities.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Choice B is incorrect because a comma after "items" doesn&rsquo;t match the semicolon used later to separate the second and third items in the series ("managing&hellip;law" and "and appointing the US poet laureate"). Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with "Managing."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c49e946e","external_id":"58385fcc-c386-4743-8021-f2d3c14f8b66","vaultid":null,"uId":"efca0611-6423-4311-8791-6691c51e00a3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>As the fourteenth US librarian of Congress, Carla Hayden has many responsibilities. These include overseeing the Library of Congress&rsquo;s collections, which boast more than 162 million <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the US Copyright Office, which registers copyright claims and advises Congress on copyright law; and appointing the US poet laureate.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"47b2505a-b6e6-4e96-bbfd-6dabc7ebedbe","content":"<p>items managing</p>"},{"id":"1cc664ee-54b3-49dc-9614-6fad90b2321f","content":"<p>items<span data-ssml-say-as=\"characters\">,</span> managing</p>"},{"id":"0acf7547-77a9-4b81-be22-a2d5b40909d4","content":"<p>items<span data-ssml-say-as=\"characters\">;</span> managing</p>"},{"id":"b56c6ffe-7ce4-43f9-af4c-7d32c354126d","content":"<p>items<span data-ssml-say-as=\"characters\">.</span> Managing</p>"}],"keys":["0acf7547-77a9-4b81-be22-a2d5b40909d4"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of elements in a complex series. It&rsquo;s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after \"items\" is conventionally used to separate the first item (\"overseeing&hellip;items\") and the second item (\"managing&hellip;law\") in a list of Hayden&rsquo;s responsibilities.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Choice B is incorrect because a comma after \"items\" doesn&rsquo;t match the semicolon used later to separate the second and third items in the series (\"managing&hellip;law\" and \"and appointing the US poet laureate\"). Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with \"Managing.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$c52652c9$SATQ$, $SATQ$973e4eb2-2841-48c6-b98f-7b86e8aac6ee$SATQ$::uuid, $SATQ$7179aa5d-15d7-4f31-a329-d7fbb067a21f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The human brain is primed to recognize faces&mdash;so much so that, due to a perceptual tendency called pareidolia, <span aria-hidden="true">______</span><span class="sr-only">blank</span> will even find faces in clouds, wooden doors, pieces of fruit, and other faceless inanimate objects. Researcher Susan Magsamen has focused her work on better understanding this everyday phenomenon.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"367917d2-b6c6-481d-9245-99ad7eb672d8","content":"<p>she</p>"},{"id":"6164f228-a41c-4d81-85fb-e5ef6fcd5a45","content":"<p>they</p>"},{"id":"087a0ace-a114-4cc4-9389-b9d35894219f","content":"<p>it</p>"},{"id":"268b9ed6-7971-40e5-8987-54291d48ed79","content":"<p>those</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["087a0ace-a114-4cc4-9389-b9d35894219f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "It" is a singular pronoun used to stand in for objects. Since the antecedent in this case is the singular noun phrase "the human brain," "it" is a perfect pronoun to use here.</p><p>Choice A is incorrect. Although "she" is a singular pronoun, it is reserved for people and animals, not objects like "the human brain." Choice B is incorrect. "They" is a plural pronoun, but we need a singular pronoun to represent the antecedent "the human brain." Choice D is incorrect. "Those" is a plural pronoun, but we need a singular pronoun to represent the antecedent "the human brain."</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M009$SATQ$, $SATQ$$SATQ$, $SATQ$00dd09e9-8f43-4e68-a15a-aae878e3bb38$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c52652c9","external_id":"973e4eb2-2841-48c6-b98f-7b86e8aac6ee","vaultid":"7179aa5d-15d7-4f31-a329-d7fbb067a21f","uId":"8dfe9668-8de6-4845-9743-e4887fad94ba","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The human brain is primed to recognize faces&mdash;so much so that, due to a perceptual tendency called pareidolia, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> will even find faces in clouds, wooden doors, pieces of fruit, and other faceless inanimate objects. Researcher Susan Magsamen has focused her work on better understanding this everyday phenomenon.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"367917d2-b6c6-481d-9245-99ad7eb672d8","content":"<p>she</p>"},{"id":"6164f228-a41c-4d81-85fb-e5ef6fcd5a45","content":"<p>they</p>"},{"id":"087a0ace-a114-4cc4-9389-b9d35894219f","content":"<p>it</p>"},{"id":"268b9ed6-7971-40e5-8987-54291d48ed79","content":"<p>those</p>"}],"keys":["087a0ace-a114-4cc4-9389-b9d35894219f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"It\" is a singular pronoun used to stand in for objects. Since the antecedent in this case is the singular noun phrase \"the human brain,\" \"it\" is a perfect pronoun to use here.</p><p>Choice A is incorrect. Although \"she\" is a singular pronoun, it is reserved for people and animals, not objects like \"the human brain.\" Choice B is incorrect. \"They\" is a plural pronoun, but we need a singular pronoun to represent the antecedent \"the human brain.\" Choice D is incorrect. \"Those\" is a plural pronoun, but we need a singular pronoun to represent the antecedent \"the human brain.\"</p>","parenttemplatename":"OSP-KA-FSS-M009","parenttemplateid":"","templateclusterid":"00dd09e9-8f43-4e68-a15a-aae878e3bb38","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$c5d39bc7$SATQ$, $SATQ$cfcb1e78-476f-40a1-8f13-5193567c4c5c$SATQ$::uuid, $SATQ$b930bcda-e90e-4dda-844e-c3658973fbc3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Scientists believe that, unlike most other species of barnacle, turtle barnacles (<em>Chelonibia testudinari</em>) can dissolve the cement-like secretions they use to attach <span aria-hidden="true">______</span><span class="sr-only">blank</span> to a sea turtle shell, enabling the barnacles to move short distances across the shell&rsquo;s surface.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"326422dd-fd3f-4bed-be32-612023c03035","content":"<p>it</p>"},{"id":"27ea6c37-75c8-4fba-9642-a7fa24337b70","content":"<p>themselves</p>"},{"id":"60f52975-e20b-484c-a789-0dafa292ea57","content":"<p>&nbsp;them</p>"},{"id":"846c84e0-4aea-43da-946d-d4fd8e6ddfd8","content":"<p>itself</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["27ea6c37-75c8-4fba-9642-a7fa24337b70"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is pronoun-antecedent agreement. The plural reflexive pronoun &ldquo;themselves&rdquo; agrees in number with the plural antecedent &ldquo;turtle barnacles,&rdquo; correctly indicating what is attached to a sea turtle shell.&nbsp;&nbsp;</p><p>Choice A is incorrect because the singular pronoun &ldquo;it&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;turtle barnacles.&rdquo; Choice C is incorrect because it results in an unclear and confusing sentence. In this context, it&rsquo;s unclear what the plural pronoun &ldquo;them&rdquo; refers to. Choice D is incorrect because the singular reflexive pronoun &ldquo;itself&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;turtle barnacles.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-695-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$33fd8903-b02a-40a8-aa42-b3840862137a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c5d39bc7","external_id":"cfcb1e78-476f-40a1-8f13-5193567c4c5c","vaultid":"b930bcda-e90e-4dda-844e-c3658973fbc3","uId":"a4beaec6-6aac-45a5-b1be-f6e3c141749b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Scientists believe that, unlike most other species of barnacle, turtle barnacles (<em>Chelonibia testudinari</em>) can dissolve the cement-like secretions they use to attach <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to a sea turtle shell, enabling the barnacles to move short distances across the shell&rsquo;s surface.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"326422dd-fd3f-4bed-be32-612023c03035","content":"<p>it</p>"},{"id":"27ea6c37-75c8-4fba-9642-a7fa24337b70","content":"<p>themselves</p>"},{"id":"60f52975-e20b-484c-a789-0dafa292ea57","content":"<p>&nbsp;them</p>"},{"id":"846c84e0-4aea-43da-946d-d4fd8e6ddfd8","content":"<p>itself</p>"}],"keys":["27ea6c37-75c8-4fba-9642-a7fa24337b70"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is pronoun-antecedent agreement. The plural reflexive pronoun &ldquo;themselves&rdquo; agrees in number with the plural antecedent &ldquo;turtle barnacles,&rdquo; correctly indicating what is attached to a sea turtle shell.&nbsp;&nbsp;</p><p>Choice A is incorrect because the singular pronoun &ldquo;it&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;turtle barnacles.&rdquo; Choice C is incorrect because it results in an unclear and confusing sentence. In this context, it&rsquo;s unclear what the plural pronoun &ldquo;them&rdquo; refers to. Choice D is incorrect because the singular reflexive pronoun &ldquo;itself&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;turtle barnacles.&rdquo; </p>","parenttemplatename":"OSP-695-SEC","parenttemplateid":"","templateclusterid":"33fd8903-b02a-40a8-aa42-b3840862137a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$c8540a5b$SATQ$, $SATQ$8913313c-428a-4db4-a846-a2f0f3114e48$SATQ$::uuid, $SATQ$54e6b84f-576f-4287-9121-4ddb020a91b1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Swedish scientists Eva Engvall and Peter Perlmann developed a method for measuring the concentration of different proteins in a biological sample. Their <span aria-hidden="true">______</span><span class="sr-only">blank</span> ELISA (enzyme-linked immunosorbent assay), is used to detect and measure proteins that indicate the presence of certain diseases.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b5d31292-3221-4b8e-8fc8-24b4fcb98e08","content":"<p>method (called</p>"},{"id":"5d463127-9ffc-478a-8bf6-de4968b51d36","content":"<p>method&mdash;called</p>"},{"id":"1c5813fc-9685-4916-8c67-d6e9e807e3ec","content":"<p>method, called</p>"},{"id":"f3432288-fd20-44f3-b67b-cfbb82c22deb","content":"<p>method called</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1c5813fc-9685-4916-8c67-d6e9e807e3ec"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;method&rdquo; pairs with the comma after the closing parenthesis to separate the supplementary element &ldquo;called ELISA (enzyme-linked immunosorbent assay)&rdquo; from the rest of the sentence. This supplementary element functions to identify the name of Engvall and Perlmann&rsquo;s method, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because an opening parenthesis can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a dash can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. </p>$SATQ$, false, 0, $SATQ$OSP-780-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$cf19ff10-286a-4da1-99a9-15dee4b30d7c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c8540a5b","external_id":"8913313c-428a-4db4-a846-a2f0f3114e48","vaultid":"54e6b84f-576f-4287-9121-4ddb020a91b1","uId":"acf878bf-33b9-4448-b52c-38e38c13c3db","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Swedish scientists Eva Engvall and Peter Perlmann developed a method for measuring the concentration of different proteins in a biological sample. Their <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> ELISA (enzyme-linked immunosorbent assay), is used to detect and measure proteins that indicate the presence of certain diseases.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b5d31292-3221-4b8e-8fc8-24b4fcb98e08","content":"<p>method (called</p>"},{"id":"5d463127-9ffc-478a-8bf6-de4968b51d36","content":"<p>method&mdash;called</p>"},{"id":"1c5813fc-9685-4916-8c67-d6e9e807e3ec","content":"<p>method, called</p>"},{"id":"f3432288-fd20-44f3-b67b-cfbb82c22deb","content":"<p>method called</p>"}],"keys":["1c5813fc-9685-4916-8c67-d6e9e807e3ec"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;method&rdquo; pairs with the comma after the closing parenthesis to separate the supplementary element &ldquo;called ELISA (enzyme-linked immunosorbent assay)&rdquo; from the rest of the sentence. This supplementary element functions to identify the name of Engvall and Perlmann&rsquo;s method, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because an opening parenthesis can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a dash can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. </p>","parenttemplatename":"OSP-780-SEC","parenttemplateid":"","templateclusterid":"cf19ff10-286a-4da1-99a9-15dee4b30d7c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$c8607bdf$SATQ$, $SATQ$3cb708e3-621b-462b-9a18-c1fb4a811d10$SATQ$::uuid, $SATQ$dc5fc1ac-5ed7-4e71-aa42-4e008606e688$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Praise Song for the Day,&rdquo; Elizabeth Alexander&rsquo;s 2009 inaugural poem, asserts that &ldquo;We cross dirt roads and highways&hellip;to see what&rsquo;s on the other side.&rdquo; Alexander&rsquo;s use of &ldquo;we&rdquo; <span aria-hidden="true">______</span><span class="sr-only">blank</span> Americans&rsquo; collective efforts and shared desire to seek new opportunity.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c9c986cb-882f-49ce-a57b-0caa7a3b33c9","content":"<p>evokes</p>"},{"id":"c8311918-ab89-470e-ab88-88eccdf27f5f","content":"<p>are evoking</p>"},{"id":"ae7bbf67-f3c5-4498-8583-5bbb18ca1e6d","content":"<p>have evoked</p>"},{"id":"224b03cd-d20d-426e-bbeb-fcc624c70182","content":"<p>evoke</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c9c986cb-882f-49ce-a57b-0caa7a3b33c9"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is subject-verb agreement. The singular verb "evokes" agrees in number with the singular subject "Alexander&rsquo;s use."</p><p>Choice B is incorrect because the plural verb "are evoking" doesn&rsquo;t agree in number with the singular subject "Alexander&rsquo;s use." Choice C is incorrect because the plural verb "have evoked" doesn&rsquo;t agree in number with the singular subject "Alexander&rsquo;s use." Choice D is incorrect because the plural verb "evoke" doesn&rsquo;t agree in number with the singular subject "Alexander&rsquo;s use."</p>$SATQ$, false, 0, $SATQ$OSP-644-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$938a64bc-fd46-4f1a-9b56-ed333